         continue\n        out.append(x)\n    return out\ndef B_parents(x):\n    out = []\n    for q in ('t', 'u'):\n        w = invT(x) if q == 't' else invT(x ^ 1)\n        if w is None:\n            out.append({'q': q, 'stage': 'Ginv-none'})\n            continue\n        zs = invP(w)\n        if not zs:\n            out.append({'q': q, 'stage': 'Pinv-none'})\n            continue\n        for z in zs:\n            out.append({'q': q, 'stage': 'candidate', 'y': 4 * z + 3})\n    return out\nprint(\"n1 helpers ok\")\n\n# Part A: admitted r=12 extensions of smallest p word ttttututttu (NO full atlas)\nBASE = 'ttttututttu'\nEXT = {}\nfor e in ('t', 'u'):\n    w = BASE + e\n    EXT[e] = {'word': w, 'admissible': adm(w)}\n    print('extension', repr(w), 'admissible:', adm(w))\n\n# bit-lift a single word to mod 2^(2L+2)\ndef lift_one(word):\n    cur = [q for q in range(16) if Q_of(q) == word[0]]\n    mod = 16\n    for j in range(1, len(word)):\n        nxt = []\n        mod *= 4\n        for q in cur:\n            for t in range(4):\n                c = q + t * (mod // 4)\n                x = c\n                ok = True\n                for jj in range(j + 1):\n                    bq = Q_of(x)\n                    if bq is None or bq != word[jj]:\n                        ok = False\n                        break\n                    x = F_of(x)\n                if ok:\n                    nxt.append(c)\n        cur = nxt\n        if not cur:\n            return []\n    return cur\nK12, D12, B12 = 20, 12, 2\nRES12 = {}\nfor e in ('t', 'u'):\n    if not EXT[e]['admissible']:\n        RES12[e] = {'admissible': False, 'reason': 'uu-forbidden' if (BASE + e).endswith('uu') else 'forbidden-factor'}\n        continue\n    w = BASE + e\n    qs = lift_one(w)\n    assert len(qs) == 1, (w, qs)\n    q = qs[0]\n    key = (q >> (2 * D12)) & 3\n    Hs = [H for H in C8['p'] if (H & 3) == key]\n    assert len(Hs) == 1, (w, Hs)\n    x = (1 << (2 * D12)) * Hs[0] + (q & ((1 << (2 * D12)) - 1))\n    assert (x & ((1 << (2 * len(w) + 2)) - 1)) == q, w\n    bw = []\n    xx = x\n    for _ in range(len(w)):\n        bq = Q_of(xx)\n        assert bq is not None\n        bw.append(bq)\n        xx = F_of(xx)\n    assert ''.join(bw) == w, w\n    prows = []\n    for pe in B_parents(x):\n        if pe['stage'] != 'candidate':\n            prows.append({'q': pe['q'], 'stage': pe['stage']})\n            continue\n        y = pe['y']\n        ql = pe['q']\n        head = y >> (2 * ((K12 - 1) - 8))\n        prows.append({'q': ql, 'y': y, 'F_verified': F_of(y) == x, 'Q_parent': Q_of(y),\n                      'bitlen': y.bit_length(), 'bitlen_criterion': 2 * (K12 - 1),\n                      'bitlen_ok': y.bit_length() == 2 * (K12 - 1),\n                      'head': head, 'head_in_C8': head in C8['p'],\n                      'qword_adm': adm(ql + w),\n                      'qualifies': bool(F_of(y) == x and Q_of(y) == ql and y.bit_length() == 2 * (K12 - 1) and head in C8['p'] and adm(ql + w))})\n    RES12[e] = {'admissible': True, 'q': q, 'H': Hs[0], 'x': x, 'x_hex': hex(x),\n                'branches12_ok': True, 'prows': prows,\n                'pass': any(p['qualifies'] for p in prows if 'qualifies' in p)}\n    print('r12', e, 'x', hex(x), 'pass:', RES12[e]['pass'], [(p['q'], p.get('F_verified'), p.get('head_in_C8'), p.get('qword_adm'), p.get('bitlen_ok')) for p in prows])\n\n# Part B: re-score stored 153 rows under CORRECTED bitlength (reuse, no new search)\nPROWS = json.load(open(PRED))['rows']\nrescore = {'pass': 0, 'fail': 0}\nfor r in PROWS:\n    kk = r['k']\n    want = 2 * (kk - 1) if r['phase'] == 'p' else 2 * (kk - 1) - 1\n    ok = False\n    for q in r['qrows']:\n        if q.get('stage') != 'candidate':\n            continue\n        if q.get('F_verified') and q.get('branch_match') and q['y'].bit_length() == want and q.get('head_in_C8') and q.get('qword_adm'):\n            ok = True\n    rescore['pass' if ok else 'fail'] += 1\nprint('rescore row-k corrected-bitlength:', rescore)\n# Part C: 32-pair head-inverse lemma probe\nLEM = []\nfor ph in ('p', 'u'):\n    m = W8[ph]\n    for H in C8[ph]:\n        hb = [(H >> i) & 1 for i in range(m)] + [0, 0]\n        for a in (0, 1):\n            for b in (0, 1):\n                xm2, xm1 = b, a\n                xs = []\n                for i in range(m + 2):\n                    xi = hb[i] ^ (xm1 | xm2)\n                    xs.append(xi)\n                    xm2, xm1 = xm1, xi\n                LEM.append({'phase': ph, 'H': H, 'incoming': [a, b], 'final_pair': xs[-2:], 'is_00': xs[-2:] == [0, 0]})\nprint('lemma 00 count:', sum(1 for e in LEM if e['is_00']), '/', len(LEM))\nfor e in LEM:\n    if not e['is_00']:\n        print('NONZERO:', e)\n\nsummary = {\n  'r12_base': BASE,\n  'extensions': {e: ({'admissible': v['admissible']} if not v['admissible'] else {'x_hex': hex(v['x']), 'pass': v['pass']}) for e, v in RES12.items()},\n  'interior_counter_persists': not any(v.get('pass') for v in RES12.values() if v['admissible']),\n  'rescore_corrected_bitlength': rescore,\n  'lemma_00': sum(1 for e in LEM if e['is_00']),\n  'lemma_total': len(LEM),\n  'criterion': 'bitlength == 2(k-1) phase p, 2(k-1)-1 phase u; head = parent>>(2((k-1)-8)) in C8; literal bitlen==k-1 was assistant misreading, never lead claim',\n}\ncanon = lambda o: json.dumps(o, sort_keys=True, separators=(', ', ': '))\nphh = {'decoder_record_tmp': hashlib.sha256(open(DEC, 'rb').read()).hexdigest(),\n       'predecessor_record_tmp': hashlib.sha256(open(PRED, 'rb').read()).hexdigest()}\nwith open(os.path.join(REPO, F_LIFT), 'rb') as fh:\n    phh[F_LIFT] = hashlib.sha256(fh.read()).hexdigest()\nwith open(os.path.join(REPO, F_OVL), 'rb') as fh:\n    phh[F_OVL] = hashlib.sha256(fh.read()).hexdigest()\nporc = subprocess.check_output(['git', 'status', '--porcelain=v1', '--untracked-files=no'], cwd=REPO).decode()\ngitc = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=REPO).decode().strip()\npeak = resource.getrusa